document.addEventListener('DOMContentLoaded', () => {
    const bgVideo = document.getElementById('bgTekken5'); // top: Tekken 5 video
    const bgJin = document.getElementById('bgTekken3');   // bottom: Jin image

    // Load the Tekken 5 video that is built into this file (see TEKKEN5_MP4_BASE64 at the bottom)
    (function loadEmbeddedVideo() {
        const bin = atob(TEKKEN5_MP4_BASE64);
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        bgVideo.src = URL.createObjectURL(new Blob([bytes], { type: 'video/mp4' }));
    })();

    /* =========================================
       1. VIDEO AUDIO + MUTE BUTTON
       ========================================= */
    const soundBtn = document.getElementById('soundBtn');
    const soundLabel = document.getElementById('soundLabel');
    let userMuted = false; // becomes true only if the visitor presses the mute button

    function refreshSoundBtn() {
        const on = !bgVideo.muted;
        soundBtn.classList.toggle('is-on', on);
        soundLabel.textContent = on ? 'Sound On' : 'Sound Off';
        soundBtn.setAttribute('aria-label', on ? 'Mute video sound' : 'Unmute video sound');
    }

    // Muted playback is always allowed by browsers, so the video never fails to start
    function playMuted() {
        bgVideo.muted = true;
        const p = bgVideo.play();
        if (p && p.catch) p.catch(() => {});
        refreshSoundBtn();
    }

    // Try to play WITH sound; browsers usually block this until the visitor interacts
    function playWithSound() {
        if (userMuted) return;
        bgVideo.muted = false;
        const p = bgVideo.play();
        if (p && p.then) {
            p.then(refreshSoundBtn).catch(playMuted);
        } else {
            refreshSoundBtn();
        }
    }

    // On load: ask for sound first, fall back to muted autoplay if the browser refuses
    playWithSound();

    // First click / key press / tap anywhere turns the sound on (unless they muted it)
    ['pointerdown', 'keydown', 'touchend'].forEach(evt =>
        window.addEventListener(evt, (e) => {
            if (e.target && e.target.closest && e.target.closest('#soundBtn')) return;
            if (bgVideo.muted && !userMuted) playWithSound();
            if (bgVideo.paused) playMuted();
        })
    );

    // Mute / unmute button
    soundBtn.addEventListener('click', () => {
        if (bgVideo.muted) {
            userMuted = false;
            playWithSound();
        } else {
            userMuted = true;
            bgVideo.muted = true;
            refreshSoundBtn();
        }
    });
    refreshSoundBtn();

    // If the video file is missing or misnamed, say so on the button instead of failing silently
    bgVideo.addEventListener('error', () => {
        soundLabel.textContent = 'Video error';
    });

    /* =========================================
       2. SMOOTH PARALLAX + CROSSFADE ENGINE
       The page scroll position is "eased" every frame, so the background
       glides instead of jumping, even with a mouse wheel.
       ========================================= */
    const EASE = 0.12;              // lower = smoother/slower glide, higher = snappier
    const root = document.documentElement;
    let targetY = window.scrollY;   // where the page really is
    let currentY = targetY;         // where the background currently is (eased)
    let running = false;

    const clamp01 = (n) => Math.min(1, Math.max(0, n));

    function render() {
        const maxScroll = Math.max(1, root.scrollHeight - window.innerHeight);
        const fraction = clamp01(currentY / maxScroll);

        // Video rolls slower than the page (parallax)
        bgVideo.style.transform = `translate3d(0, ${(currentY * 0.16).toFixed(2)}px, 0) scale(1.06)`;

        // Jin image rolls upward as you approach the bottom
        bgJin.style.transform = `translate3d(0, ${((fraction - 0.55) * 180).toFixed(2)}px, 0) scale(1.06)`;

        // Crossfade: video fades OUT while the Jin image fades IN (60% -> 90% of the scroll)
        const fade = clamp01((fraction - 0.60) / 0.30);
        bgJin.style.opacity = fade.toFixed(3);
        bgVideo.style.opacity = (1 - fade).toFixed(3);

        // Neon glow: low over the video (top), ramps up toward the bottom
        root.style.setProperty('--neon-glow', (0.12 + 0.88 * clamp01(fraction / 0.6)).toFixed(3));
    }

    function loop() {
        const diff = targetY - currentY;
        if (Math.abs(diff) < 0.1) {
            currentY = targetY;
            render();
            running = false;      // fully caught up: stop until the next scroll
            return;
        }
        currentY += diff * EASE;
        render();
        requestAnimationFrame(loop);
    }

    function onScroll() {
        targetY = window.scrollY;
        if (!running) {
            running = true;
            requestAnimationFrame(loop);
        }
        // Keep the video running while scrolling even if the browser paused it
        if (bgVideo.paused) {
            const p = bgVideo.play();
            if (p && p.catch) p.catch(() => {});
        }
    }

    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    render();

    /* =========================================
       3. TIC-TAC-TOE GAME
       ========================================= */
    const cells = document.querySelectorAll('.cell');
    const statusText = document.getElementById('gameStatus');
    const resetBtn = document.getElementById('resetBtn');

    let board = ["", "", "", "", "", "", "", "", ""];
    let currentPlayer = "X";
    let gameActive = true;

    const winConditions = [
        [0, 1, 2], [3, 4, 5], [6, 7, 8],
        [0, 3, 6], [1, 4, 7], [2, 5, 8],
        [0, 4, 8], [2, 4, 6]
    ];

    function updateStatus() {
        statusText.textContent = `Player ${currentPlayer}'s Turn`;
        statusText.style.color = currentPlayer === "X" ? "var(--neon-cyan)" : "var(--neon-magenta)";
        statusText.style.textShadow = `0 0 10px ${currentPlayer === "X" ? "rgba(0, 243, 255, 0.4)" : "rgba(255, 0, 234, 0.4)"}`;
    }

    function checkWin() {
        let roundWon = false;

        for (let i = 0; i < winConditions.length; i++) {
            const [a, b, c] = winConditions[i];
            if (board[a] && board[a] === board[b] && board[a] === board[c]) {
                roundWon = true;
                break;
            }
        }

        if (roundWon) {
            statusText.textContent = `PLAYER ${currentPlayer} WINS!`;
            statusText.style.color = "var(--neon-gold)";
            statusText.style.textShadow = "0 0 15px var(--neon-gold)";
            gameActive = false;
            return;
        }

        if (!board.includes("")) {
            statusText.textContent = "IT'S A DRAW!";
            statusText.style.color = "var(--text-main)";
            statusText.style.textShadow = "none";
            gameActive = false;
            return;
        }

        currentPlayer = currentPlayer === "X" ? "O" : "X";
        updateStatus();
    }

    cells.forEach(cell => {
        cell.addEventListener('click', (e) => {
            const index = e.target.getAttribute('data-index');
            if (board[index] !== "" || !gameActive) return;

            board[index] = currentPlayer;
            e.target.textContent = currentPlayer;
            e.target.classList.add(currentPlayer.toLowerCase());

            checkWin();
        });
    });

    resetBtn.addEventListener('click', () => {
        board = ["", "", "", "", "", "", "", "", ""];
        currentPlayer = "X";
        gameActive = true;

        cells.forEach(cell => {
            cell.textContent = "";
            cell.classList.remove('x', 'o');
        });

        updateStatus();
    });

    updateStatus();
});

